#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#define MAX 100

void bfs(int graph[MAX][MAX], int n, int start) {
    bool visited[MAX] = {false};
    int queue[MAX], front = 0, rear = 0;

    visited[start] = true;
    queue[rear++] = start;

    while (front < rear) {
        int node = queue[front++];
        printf("%d ", node);

        for (int i = 0; i < n; i++) {
            if (graph[node][i] && !visited[i]) {
                visited[i] = true;
                queue[rear++] = i;
            }
        }
    }
}

int main() {
    int graph[MAX][MAX] = {0};
    /* Add edges */
    graph[0][1] = graph[1][0] = 1;
    graph[0][2] = graph[2][0] = 1;
    graph[1][3] = graph[3][1] = 1;
    bfs(graph, 6, 0);
    return 0;
}

